import { useState, memo } from 'react';

// TODO: wrap with React.memo so it only re-renders when value changes
function ExpensiveChild({ value }) {
  console.log('ExpensiveChild rendered');
  return <p data-testid="child-value">{value}</p>;
}

const MemoizedChild = memo(ExpensiveChild);

export default function Parent() {
  const [value, setValue] = useState('hello');
  const [counter, setCounter] = useState(0);

  return (
    <div>
      <MemoizedChild value={value} />
      <p data-testid="counter">{counter}</p>
      <button data-testid="change-value" onClick={() => setValue(v => v + '!')}>Change Value</button>
      <button data-testid="increment" onClick={() => setCounter(c => c + 1)}>Increment Counter</button>
    </div>
  );
}
